insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('b906915f-47e6-5700-bc1b-b06bf8a6eab0', 'sbw', 6, 'How to get better sleep (so you can get lean faster)', 'https://youtu.be/BiSQJh59EkM', 'Any time I have a client who is doing everything right, but not losing weight, it''s their sleep

Meaning, they are:

- drinking a gallon of water
- hitting their calories 7 days a week
- eating enough protein
- getting 10,000 steps a day
- exercising 2-3x week

... the ONLY aspect that can still prevent you from losing weight, is not getting enough sleep

You might think you''re ''building muscle'' in the gym

Or that you''re burning fat doing cardio

But building muscle and burning fat ONLY happens when you''re asleep

Your body needs to be ''shut off'' for that to happen

And I see it countless times where women put in hard work in the gym & kitchen

... only to get frustrated by their lack of progress because they simply don''t sleep enough

Here''s a video I made for you on this

In it I''ll tell you how many hours you should aim for

Along with some tips on achieving deeper sleep (which promotes better recovery)', false) on conflict (id) do update set title = excluded.title, video_url = coalesce(public.lessons.video_url, excluded.video_url), body = coalesce(public.lessons.body, excluded.body), retired = excluded.retired;
insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('868ac99b-12a2-599f-8e47-f09051231eed', 'sbw', 7, 'How to control your portions every time you eat', 'https://youtu.be/vL7b5ke5M6g', 'Calories are the #1 thing that matter most when losing weight

