insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('193c27a7-af5a-5e77-82c2-54aaefc61006', 'sbw', 8, 'The 9 Best Supplements for Health & Performance', 'https://youtu.be/0M8lQ1aHWWE', 'Supplements only make a 3% difference in your weight loss at most

