insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('953bc904-7ce3-57d3-b1e9-4d558e5f16e8', 'sbw', 12, 'How long does it take to get lean?', 'https://youtu.be/RX3lUu64tsc', 'I''ve hired many coaches in the past, primarily for growing my business

