insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('1b6e84e1-a771-5580-8cb1-484c4f7257f7', 'sbw', 30, 'How soon can you work the same muscle again?', 'https://youtu.be/0EdlXqxp5Ss', 'Going over 80-90% of your 1RM will put a big strain on your cns.

