insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('2f285fde-b39f-5257-a7bd-0fd57992ff82', 'sbw', 31, 'What is ''carb cycling''?', 'https://youtu.be/2NaROk1ZDhw', 'Going ''low-carb'' is more of a quick fix than many realize.

