insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('c022e68b-9c37-5946-a90d-6f156278ffb6', 'sbw', 32, 'All of the ''Best Digesting Foods'' you should prioritize in your meals.', null, 'Eating good food is one thing, being able to digest it is another.

Here''s a list with all the best digesting foods you can eat.

Vegetables: Eggplant, green beans, carrots, cucumbers, lettuce, potatoes, zucchini, bell peppers, bok choy, celery, chives, kale, pumpkin, radishes, spinach, tomatoes, winter squash, and yams

Fruits: Cantaloupe, kiwi, mandarin, orange, pineapple, grapes, strawberries, blueberries

Dairy and alternatives: Almond milk, brie cheese, feta cheese, hard cheeses, lactose-free milk, oat milk, rice milk, soy milk, lactose-free yogurt, gelati, and sorbet

Proteins: Eggs, firm tofu, plain cooked meats/poultry/seafood, tempeh, chicken, beef, turkey, cold cuts, lamb

Cereals, grains, and breads: Corn flakes, oats, quinoa/rice/corn pasta, sourdough spelt bread, gluten free bread or cereal products, 100% spelt bread, rice, polenta

Sugars and sweeteners: Dark chocolate, maple syrup, rice malt syrup, table sugar

Nuts and seeds: Macadamias, peanuts, pumpkin seeds, walnuts

NOTE: You do not need to swap out all foods that are not on this list immediately. Merely use this as advice, especially if you ''feel'' like certain foods don''t sit well with you. Swap them out for foods on this list and see how you do with them.', false) on conflict (id) do update set title = excluded.title, video_url = coalesce(public.lessons.video_url, excluded.video_url), body = coalesce(public.lessons.body, excluded.body), retired = excluded.retired;
insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('d0e3cd3f-7c3f-551c-a2cc-1cb1801ee8bd', 'sbw', 33, 'My 4 favorite ab exercises to ''build'' a 6-pack.', 'https://www.youtube.com/watch?v=E9dW7IK_UPk', 'If you want abs...

Then I''d hate for you to waste time on the ''crunch machine'' at the big gym

There are actually 4 exercises way better than any machine can ever replicate

It''s the same 4 I do myself - they''re tough enough to actually damage your abs (so your 6-pack ''grows back'' better)

But before you click the links below - reminder:

You will never have a 6-pack if your bodyfat percentage is high

That might sound harsh, but it''s science.

You already have a 6-pack

You might not be able to ''see'' it though

If you can''t ''see'' yours yet, and you want it NOW then your best bet is to:

- get implants
- paint
- lean into a fence

But if you''re motivated to get one for real, then first start paying attention to how many calories you''re eating.

Visualize yourself actually having one.

So much that you start finding it ''normal''

Keep visualizing, and focus on your habits, consistency, and your mindset.

Once you''re mentally stable enough to eat a consistent amount of calories, and you know how to have protein with every meal...

Then you''re on Interstate 63, headed straight towards SP City.

(''6'' for sixpack, ''3'' for city because c is the 3rd letter of the alphabet)', false) on conflict (id) do update set title = excluded.title, video_url = coalesce(public.lessons.video_url, excluded.video_url), body = coalesce(public.lessons.body, excluded.body), retired = excluded.retired;
insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('801e3765-6bdc-5616-a0a4-f3b270574097', 'sbw', 34, 'Everything you need to know for a bigger butt', 'https://youtu.be/iQPXqyeEzr8', 'The 2 hardest body parts to ''get right'' are:

