And other stuff', false) on conflict (id) do update set title = excluded.title, video_url = coalesce(public.lessons.video_url, excluded.video_url), body = coalesce(public.lessons.body, excluded.body), retired = excluded.retired;
insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('d047241c-dd8d-53d6-99ba-ea233a7b7c0e', 'sbw', 35, '6 mistakes to avoid when getting ready for your pic', 'https://youtu.be/903oaMooWx8', 'Most people mess it all up right before they have their ''event''

