insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('8227e958-8706-597f-9980-207887ef660d', 'sbw', 36, 'Big Lifts vs Isolation Lifts...', 'https://www.youtube.com/watch?v=jDe5rj_xudQ', 'Lifting weights will build muscle and increase your strength.

