insert into public.lessons (id, kind, number, title, video_url, body, retired) values ('5bc1b2c9-bfad-5b59-8f1d-e1a99279861c', 'sbw', 37, 'Every meal should be awesome', 'https://youtu.be/Ysz38MbaAC0', 'Whatever calories you''re going to nourish your body with - they better be awesome

